1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	
14	/**
15	 * The MHPCO price list prices each main item type by its own tariff row, but
16	 * prices every component by one rule: 25 G per component, whatever its kind.
17	 */
18	const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
19	  sword: 100,
20	  amulet: 60,
21	  staff: 80,
22	  potion: 40,
23	};
24	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
25	const COMPONENT_BASE_PREMIUM = 25;
26	
27	function isComponent(type: string): boolean {
28	  return COMPONENT_TYPES.has(type);
29	}
30	
31	function basePremiumFor(type: string): number {
32	  return isComponent(type) ? COMPONENT_BASE_PREMIUM : MAIN_ITEM_BASE_PREMIUM[type];
33	}
34	
35	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
36	const PERCENT = 100;
37	
38	// Percentages are kept as exact fractions (integer numerator over PERCENT);
39	// scaling by a float rate such as 0.1 yields artefacts like 115.00000000000001.
40	function percentOf(amount: number, percent: number): number {
41	  return (amount * percent) / PERCENT;
42	}
43	
44	/** MHPCO rounds a premium up: every fraction of a G falls to the customer. */
45	function roundInMHPCOsFavor(premium: number): number {
46	  return Math.ceil(premium);
47	}
48	
49	export function policyBasePremium(items: Item[]): number {
50	  return items.reduce((total, item) => total + basePremiumFor(item.type), 0);
51	}
52	
53	export function quote(customer: Customer, items: Item[], previousContracts: number): number {
54	  const policyBase = policyBasePremium(items);
55	  const firstInsuranceSurcharge = percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
56	  return roundInMHPCOsFavor(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
57	}
